<div x-data="lecturerEvaluationForm({{ !empty($supervisor) ? 'true' : 'false' }},{{ !empty($ta) ? 'true' : 'false' }})" class="space-y-6">
    <a :href="backUrl" class="inline-flex items-center gap-2 text-sm hover:underline"><x-capstone::icon name="ArrowLeft" class="h-4 w-4" />Back to Evaluations</a>
    <div><h1 class="text-3xl font-bold tracking-tight" x-text="viewOnly?'View Scores':supervisor?'Supervisor Evaluation':'Student Evaluation'"></h1><p class="mt-2 text-muted-foreground" x-text="evaluationLabels[type]||(type==='TA_DEFENSE'?'Sidang Tugas Akhir':data?.schedule?.type||'Seminar')"></p></div>
    @include('capstone::partials.loading')
    <template x-if="data && !loading && !error"><div class="grid gap-6 lg:grid-cols-3">
        <aside class="space-y-4"><section class="rounded-xl border bg-card p-6"><h2 class="font-semibold" x-text="data.group?.code||data.group?.name||'Group '+data.group?.id"></h2><p class="mt-3 text-sm text-muted-foreground" x-text="data.group?.title?.title||''"></p><div class="mt-4 space-y-2 text-sm"><p x-text="date(data.schedule?.date)"></p><p x-text="data.schedule?.room||'-'"></p><p x-show="data.schedule?.evaluation_deadline" x-text="'Deadline: '+date(data.schedule?.evaluation_deadline,true)"></p></div></section>
            <section class="rounded-xl border bg-card p-6"><h2 class="mb-4 font-semibold">Score Summary</h2><template x-for="student in students" :key="student.id"><div class="flex items-center justify-between gap-2 border-t py-3 text-sm"><span x-text="student.name"></span><strong x-text="total(student.id)"></strong></div></template><p class="mt-3 text-xs text-muted-foreground">Weighted score out of 100.</p></section>
        </aside>
        <form @submit.prevent="submit()" class="space-y-4 lg:col-span-2">
            <p x-show="viewOnly" class="rounded-lg border border-blue-200 bg-blue-50 p-4 text-sm text-blue-800">Viewing saved scores.</p>
            <p x-show="!components.length || !students.length" class="rounded-lg border p-6 text-sm text-muted-foreground">No assessment components or students are available for this evaluation.</p>
            <fieldset :disabled="viewOnly || saving" class="space-y-4"><template x-for="component in components" :key="component.id"><section class="rounded-xl border bg-card p-6"><div class="flex items-start justify-between gap-3"><h2 class="font-semibold" x-text="component.name||component.code"></h2><span class="shrink-0 rounded border px-2 py-1 text-xs" x-text="'Weight: '+component.weight"></span></div><p class="mt-2 whitespace-pre-wrap text-sm text-muted-foreground" x-text="component.description"></p>
                <div class="mt-5 space-y-4"><template x-for="student in students" :key="student.id"><div class="rounded-lg border bg-muted/20 p-4"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-sm font-medium" x-text="student.name"></p><p class="text-xs text-muted-foreground" x-text="student.nim"></p></div><label class="flex items-center gap-2 text-sm"><span>Score</span><input type="number" :min="minimum" max="100" step="0.01" required x-model="scores[component.id+'_'+student.id]" :aria-label="'Score for '+student.name+' - '+component.name" class="h-10 w-24 rounded-md border bg-background px-3 text-center"></label></div><label class="mt-3 grid gap-2 text-xs text-muted-foreground">Notes<textarea x-model="notes[component.id+'_'+student.id]" rows="2" maxlength="5000" class="rounded-md border bg-background p-3 text-sm text-foreground" placeholder="Feedback (optional)..."></textarea></label></div></template></div>
            </section></template>
                <div x-show="!supervisor" class="rounded-xl border bg-card p-6"><label class="grid gap-2 text-sm font-medium">Examination Result<select x-model="result" :required="!supervisor" class="h-10 rounded-md border bg-background px-3"><option value="">Select result</option><option value="PASS">Pass</option><option value="FAIL">Fail</option></select></label></div>
            </fieldset>
            <div class="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700" x-show="errors.root" role="alert"><p x-text="errors.root"></p><template x-for="(messages,key) in errors" :key="key"><p x-show="key!=='root'" x-text="Array.isArray(messages)?messages.join(' '):''"></p></template></div>
            <div class="flex justify-end" x-show="!viewOnly"><x-capstone::button type="submit" ::disabled="saving || !complete || (!supervisor && !result)"><span x-text="saving?'Saving...':'Submit Evaluation'"></span></x-capstone::button></div>
        </form>
    </div></template>
</div>
